"""Write my4-zeroshot-terms.md («Pāli = Burmese», grouped) from the tables of my4_formulas (and make_sample).

Called by make_sample.py (write_terms(F, path)); reads only the module tables, writes only the terms file.
"""
import unicodedata


def write_terms(F, path):
    T = []
    src = lambda p: f" (pi-{F.WITNESS[p][0]} {F.WITNESS[p][1]})" if p in F.WITNESS else " (new)"
    T += ["# pi-4 Burmese zero-shot: formulas and terms («Pāli = Burmese»)", "",
          "Generated by make_sample.py from my4_formulas.py. Values marked (pi-N ^id) are read from, or checked "
          "against, the FINAL pi-1 / pi-2 / pi-3 Burmese (rails text) at that segment; (new) = proposed for pi-4. "
          "For review by the user.", ""]
    T += ["## Book title and frame", "",
          f"Puggalapaññattipāḷi (book title) = {F.TITLE} (new; Burmese only)",
          f"Abhidhammapiṭake = {F.ABHI} (pi-1 / pi-2 / pi-3)",
          f"Namo tassa bhagavato arahato sammāsambuddhassa = {F.NAMO} (pi-1 / pi-2 / pi-3)",
          f"Puggalapaññattimātikā niṭṭhitā. = {F.FIXED['Puggalapaññattimātikā niṭṭhitā.']} (new; pi-1 «Mātikā "
          f"niṭṭhitā» pattern)",
          f"Puggalapaññattipakaraṇaṃ niṭṭhitaṃ. = {F.FIXED['Puggalapaññattipakaraṇaṃ niṭṭhitaṃ.']} (new; pi-1 / pi-2 / "
          f"pi-3 pattern)",
          f"paññatti = {F.PANNATTI} (pi-1 ^1-M2-108); puggala = {F.PUGGALA} (pi-1 / pi-2); persons are counted "
          f"«{F.PUGGALA} N{F.CL_P}» (pi-2 ^2-643), things «N{F.CL}»", ""]
    T += ["## Headings and colophons", "",
          f"Mātikā (heading ###) = {F.HEAD['Mātikā']} (pi-1)", f"Niddeso (heading ###) = {F.HEAD['Niddeso']} (pi-1 / pi-2 «-niddeso»)"]
    for s in F.NUM_STEM:
        T.append(f"{s}uddeso (heading ####) = {F.HEAD[s + 'uddeso']} (pi-1 Uddeso = «{F.UDDESA}»)")
    for s in F.NUM_STEM:
        T.append(f"{s}puggalapaññatti (chapter heading ####) = {F.HEAD[s + 'puggalapaññatti']} (new)")
    for s in F.NUM_STEM:
        T.append(f"{s}ṃ. = {F.COLO[s + 'ṃ']}။ (pi-1 / pi-2)")
    for s in F.NUM_STEM:
        w = " (pi-1 / pi-2)" if s in ("Ekaka", "Duka", "Tika") else " (pi-1 pattern)"
        T.append(f"{s}niddeso. = {F.COLO[s + 'niddeso']}။{w}")
    T += ["", "## The six designations (1-matika ^4-M-1 … ^4-M-6)", "",
          "Cha paññattiyo = " + f"{F.PANNATTI} ခြောက်{F.CL}"]
    for s in ("khandha", "āyatana", "dhātu", "sacca", "indriya", "puggala"):
        T.append(f"{s}paññatti = {F.pannatti_my(s)}")
    T += ["Kittāvatā Xānaṃ Xpaññatti? = Xတို့၏ X သတ်မှတ်ချက်သည် အဘယ်မျှ ရှိသနည်း။",
          "Yāvatā LIST – a, b, c; ettāvatā Xānaṃ Xpaññatti. = LIST – a၊ b၊ c ရှိသမျှ၊ ဤမျှသည် Xတို့၏ X သတ်မှတ်ချက် "
          "ဖြစ်သည်။",
          "List heads and items: FINAL pi-2 (^2-1, ^2-154, ^2-183, ^2-206, ^2-218, ^2-219):"]
    T += [f"  {p} = {m}{src(p[0].upper() + p[1:])}" for p, m in F.LIST_HEAD.items()]
    T += [f"  {p} = {m}{src(p)}" for p, m in F.LIST_ITEM.items()]
    T += ["", "## The definition frame", "",
          f"Katamo ca puggalo X? = X{F.Q_TAIL} (two types «A B?» = «Aနှင့် B{F.Q_TAIL}»)",
          f'ayaṃ vuccati puggalo "X". = {F.VUCCATI.format("X")} (after «–» or a full stop)',
          f'ime vuccanti puggalā "X". = {F.VUCCANTI.format("X")} (the name stays singular)',
          f"Idhekacco puggalo = {F.IDHA} (pi-2 ^2-925 «Idhekacco …»)",
          f"Atthekacco puggalo PRED (mātikā) = {F.ATTHI} PRED (NAME + «{F.COP}»); parts joined by «၊», a full stop "
          f"stays «။»",
          'X puggalo "NAME". (^4-20, ^4-21) = X ပုဂ္ဂိုလ်သည် “NAME” ဖြစ်သည်။',
          f"Plural subjects: «… NAME ဖြစ်ကြ၏။»; a name before «puggalo» (mātikā) = adjective: «…သူ» -> «…သော "
          f"{F.PUGGALA}», e.g. arukūpamacitto puggalo = {F.adj(F.NAME['arukūpamacitto'])}",
          "Negation: free na / no / neva at clause level and before a noun = «… မဟုတ်»; before a finite verb or an "
          "agent word = «မ» + verb (pi-2 practice, e.g. ^2-932 «မယုံကြည်»); privative a- / an- = «မ» + verb, or "
          "«X မဟုတ်သူ» for a noun (anariyo, asappuriso)", ""]
    T += ["## Shared sentences of the definitions (my4_formulas.SENT)", ""]
    for p, m in F.SENT.items():
        if p in getattr(F, "_UNIQUE_KEYS", set()):
            continue
        T.append(f"{p} = {m}")
    T += ["", "## Reused terms (FINAL pi-1 / pi-2 / pi-3, witnessed)", ""]
    for k, (b, bid, my) in F.WITNESS.items():
        T.append(f"{k} = {my} (pi-{b} {bid})")
    T += ["", "## Person-type names of the mātikā (NAME; the same in mātikā, heading and definition)", ""]
    sec = {1: "Ekaka (ones)", 2: "Duka (twos)", 3: "Tika (threes)", 4: "Catukka (fours)", 5: "Pañcaka (fives)",
           8: "Aṭṭhaka (eights)"}
    alias_of = {}
    for a, k in F.ALIAS.items():
        alias_of.setdefault(k, []).append(a)
    for s, title in sec.items():
        T += [f"### {title}", ""]
        for k, my in F.NAME.items():
            if F._SRC[k] == s:
                al = f" (also: {', '.join(alias_of[k])})" if k in alias_of else ""
                T.append(f"{k} = {my}{al}")
        T.append("")
    T += ["Plural forms of the definitions: " + "; ".join(f"{p} = {F.NAME[k]}" for p, k in F.PLURAL.items()), ""]
    T += ["## Group names (members are defined in the later chapters)", ""]
    T += [f"N {g} puggalā = {m} {F.PUGGALA} N{F.CL_P}" for g, m in F.GROUP.items()]
    T += [f"Dve puggalā {g} = {m} {F.PUGGALA} နှစ်{F.CL_P}" for g, m in F.GROUP_POST.items()]
    T += [f"Pañca {g} = {m} ငါး{F.CL_P}" for g, m in F.GROUP_NOUN.items()]
    T += ["", "## Mātikā predicates «atthekacco puggalo …» (not «NAME ဖြစ်၏»)", ""]
    T += [f"{p} = {m}" for p, m in F.PRED.items()]
    T += ["", "## Variant readings", "",
          "[X (sigla)] = [ပါဌ်ကွဲ (Sigla): X] (word) / [စာလုံးပေါင်းကွဲ (Sigla): X] (spelling); a sutta reference "
          "«a. ni. 4.135» = «၊ “အင်္ဂုတ္တရနိကာယ်” 4.135» (pi-2 ^2-957)"]
    T += [f"{p} = {k}" for p, k in F.VAR_KIND.items()]
    path.write_text(unicodedata.normalize("NFC", "\n".join(T) + "\n"), encoding="utf-8")
    print(f"wrote {path.name}")
